
% Convert grid path into boat coordinates (meters)

% Use the path generated by test_theta_star
if isempty(path)
    error('No Theta* path is available.');
end

% Grid start and goal used in your test
start = [5 5];
goal  = [90 90];

% Physical start and destination
x_start = 0;
y_start = 0;
x_goal = 980;
y_goal = 100;

% Convert grid columns to X and rows to Y
x_waypoints = x_start + ...
    (path(:,2)-start(2)) / (goal(2)-start(2)) ...
    * (x_goal-x_start);

y_waypoints = y_start + ...
    (start(1)-path(:,1)) / (start(1)-goal(1)) ...
    * (y_goal-y_start);

% Store as N-by-2 array: [X, Y]
waypoints = [x_waypoints, y_waypoints];

% Display a few waypoints
disp('First five boat waypoints:');
disp(waypoints(1:min(5,end),:));

% Plot the converted route
figure;
plot(waypoints(:,1), waypoints(:,2), 'b-o');
hold on;
plot(x_start, y_start, 'go', 'MarkerFaceColor','g');
plot(x_goal, y_goal, 'ro', 'MarkerFaceColor','r');
axis equal;
grid on;
xlabel('X Position (m)');
ylabel('Y Position (m)');
title('Theta* Route in Boat Coordinates');
legend('Planned route','Start','Destination');
